import{_ as a,o as s,c as r,a5 as n}from"./chunks/framework.CXroN2RO.js";const o="/study/images/tools/crash-dumps-and-symbols.svg",h=JSON.parse('{"title":"クラッシュダンプとPDBで停止位置をたどる","description":"","frontmatter":{"title":"クラッシュダンプとPDBで停止位置をたどる","study":{"source":"新規執筆","status":"published","summary":"Windowsのユーザーモードダンプから例外、レジスター、モジュールを読み、同じビルドのPDBで関数とソース行を調べる。","section":"reference","format":"article","domain":"tools","aliases":["クラッシュダンプ","ミニダンプ","minidump","PDB","シンボル","WinDbg","ASLR","RVA","例外コンテキスト"],"verification":"Microsoftのユーザーモードダンプ形式、PDB照合とWinDbgのコマンド資料に照合（2026-11-06）"}},"headers":[],"relativePath":"tools/windows/crash-dumps-and-symbols.md","filePath":"tools/windows/crash-dumps-and-symbols.md"}'),t={name:"tools/windows/crash-dumps-and-symbols.md"};function d(i,e,c,p,l,m){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="クラッシュダンプとpdbで停止位置をたどる" tabindex="-1">クラッシュダンプとPDBで停止位置をたどる <a class="header-anchor" href="#クラッシュダンプとpdbで停止位置をたどる" aria-label="Permalink to &quot;クラッシュダンプとPDBで停止位置をたどる&quot;">​</a></h1><p>Windowsのゲームがクラッシュし、現場で再現できないときでも、クラッシュダンプに残った状態を調べられます。例外を記録したダンプには、例外コード、発生したスレッド、レジスターの値などが含まれます。ロード済みのEXEやDLLの位置を合わせると、停止した命令がどのモジュールのどこにあったかが分かります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/minidumpapiset/ns-minidumpapiset-minidump_exception_stream" target="_blank" rel="noreferrer">Microsoftの例外情報ストリーム</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/analyzing-a-user-mode-dump-file" target="_blank" rel="noreferrer">ユーザーモードダンプの解析</a></p><h2 id="モジュールの先頭から何バイトかを求める" tabindex="-1">モジュールの先頭から何バイトかを求める <a class="header-anchor" href="#モジュールの先頭から何バイトかを求める" aria-label="Permalink to &quot;モジュールの先頭から何バイトかを求める&quot;">​</a></h2><p>実行中の命令アドレスは、プロセスの仮想アドレス（VA）です。ロードされたモジュールのベースアドレスを引くと、そのモジュールの先頭からの位置を示すRVAになります。ASLRによって別の実行でベースが変わっても、同じバイナリの同じ命令は同じRVAで表せます。<code>game+0x1234</code> の <code>0x1234</code> はモジュールの先頭からの距離で、<code>game!UpdateActor+0x34</code> の <code>0x34</code> は関数の先頭からの距離です。<a href="https://learn.microsoft.com/en-us/windows/win32/debug/pe-format" target="_blank" rel="noreferrer">MicrosoftのPE形式とRVA</a> · <a href="/study/os/pe-loading-and-imports.html">PEのロードとインポート</a></p><figure class="study-figure"><img src="'+o+`" alt="例外コンテキストのRIPが00007ff7 40001234、game.exeのロードベースが00007ff7 40000000なら、差はRVA 0x1234。ビルドの識別情報が一致するPDBを使うと、停止位置をUpdateActorの先頭から0x34、Actor.cppの87行目に対応づけられる。" width="760" height="320" loading="lazy"><figcaption>命令のVAとモジュールのロードベースはダンプから読みます。関数名やソース行は、対応するデバッグ情報を使って調べます。<a href="/study/images/tools/crash-dumps-and-symbols.svg" target="_blank" rel="noopener noreferrer">アドレスの対応図を拡大</a></figcaption></figure><h2 id="実行ファイルとpdbの組を照合する" tabindex="-1">実行ファイルとPDBの組を照合する <a class="header-anchor" href="#実行ファイルとpdbの組を照合する" aria-label="Permalink to &quot;実行ファイルとPDBの組を照合する&quot;">​</a></h2><p>WindowsのネイティブPDBには、関数名、ソース行、ローカル変数を調べるためのデバッグ情報を記録できます。MSVCのPDBを照合する場合、EXEやDLLにも記録された署名とAgeを使います。現行のMSVCで一般的なCodeView形式では、署名はGUIDです。Ageは一致を確かめるための値で、経過時間として扱いません。ファイル名や製品バージョンが同じでもビルドは異なり得るため、出荷したバイナリと対応するPDBをビルドごとに保管します。<a href="https://learn.microsoft.com/en-us/visualstudio/debugger/debug-interface-access/idiadatasource-loadandvalidatedatafrompdb" target="_blank" rel="noreferrer">Microsoft DIAのPDB照合</a> · <a href="/study/tools/build/build-configurations.html">ビルド構成とシンボル</a></p><p>PDBが手元にない場合にも、ダンプに収録された例外コードやレジスター、モジュール名とRVAは調べられます。ダンプから読めるメモリは収録された範囲に限られ、最適化で消えたローカル変数はPDBが一致していても値を表示できない場合があります。最適化で複数の処理が同じ命令に対応したときは、表示されたソース行に加えて命令とレジスターを読みます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/minidumpapiset/ne-minidumpapiset-minidump_type" target="_blank" rel="noreferrer">Microsoftのミニダンプに収録する情報</a> · <a href="https://learn.microsoft.com/en-us/visualstudio/debugger/how-to-debug-optimized-code" target="_blank" rel="noreferrer">最適化済みコードのデバッグ</a></p><h2 id="windbgで例外から調べる" tabindex="-1">WinDbgで例外から調べる <a class="header-anchor" href="#windbgで例外から調べる" aria-label="Permalink to &quot;WinDbgで例外から調べる&quot;">​</a></h2><p>WinDbgで例外情報を含むユーザーモードのクラッシュミニダンプを開きます。次の例では、対象が <code>game.exe</code> で、そのビルドのPDBを <code>C:\\build\\symbols</code> に保管しています。新しい解析セッションで <code>.symfix</code> を使い、Microsoftの公開シンボルサーバーを設定してから、自分のPDBの場所を追加します。<code>lmv m game</code> で <code>game</code> のロード範囲とシンボルの状態を確認します。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/symbol-path" target="_blank" rel="noreferrer">WinDbgのシンボルパス</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debuggercmds/-symfix--set-symbol-store-path-" target="_blank" rel="noreferrer">WinDbgの <code>.symfix</code></a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debuggercmds/-reload--reload-module-" target="_blank" rel="noreferrer">WinDbgの <code>.reload</code></a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debuggercmds/lm--list-loaded-modules-" target="_blank" rel="noreferrer">WinDbgの <code>lm</code></a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.symfix</span></span>
<span class="line"><span>.sympath+ C:\\build\\symbols</span></span>
<span class="line"><span>.reload /f game.exe</span></span>
<span class="line"><span>lmv m game</span></span>
<span class="line"><span>!analyze -v</span></span>
<span class="line"><span>.exr -1</span></span>
<span class="line"><span>.ecxr</span></span>
<span class="line"><span>k</span></span>
<span class="line"><span>u @rip L1</span></span></code></pre></div><p><code>!analyze -v</code> で概要を見たあと、<code>.exr -1</code> で例外の種類と引数を読みます。<code>.ecxr</code> は例外時のレジスターコンテキストを選ぶので、その直後の <code>k</code> と <code>u @rip L1</code> で例外を起こしたスレッドのスタックと、<code>RIP</code> が指す命令を調べられます。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debuggercmds/-analyze" target="_blank" rel="noreferrer">WinDbgの <code>!analyze</code></a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debuggercmds/-exr--display-exception-record-" target="_blank" rel="noreferrer">WinDbgの <code>.exr</code></a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debuggercmds/-ecxr--display-exception-context-record-" target="_blank" rel="noreferrer">WinDbgの <code>.ecxr</code></a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debuggercmds/k--kb--kc--kd--kp--kp--kv--display-stack-backtrace-" target="_blank" rel="noreferrer">WinDbgの <code>k</code></a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debuggercmds/u--unassemble-" target="_blank" rel="noreferrer">WinDbgの <code>u</code></a></p><p>下は値の読み方を示すために作った表示例です。PDBで名前が解決され、ソース行も取得できた場合を想定しています。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ExceptionCode:    c0000005</span></span>
<span class="line"><span>ExceptionAddress: 00007ff7\`40001234</span></span>
<span class="line"><span>Parameter[0]:    00000000\`00000001</span></span>
<span class="line"><span>Parameter[1]:    00000000\`00000010</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rcx=00000000\`00000000</span></span>
<span class="line"><span>rip=00007ff7\`40001234</span></span>
<span class="line"><span>game!UpdateActor+0x34 [Actor.cpp @ 87]:</span></span>
<span class="line"><span>00007ff7\`40001234 894110  mov dword ptr [rcx+10h],eax</span></span></code></pre></div><p><code>0xC0000005</code> はアクセス違反です。この例では最初の例外引数が1なので書き込みで、次の引数が書き込み先の <code>0x10</code> です。<code>RCX</code> は0で、命令が書き込もうとした先は <code>RCX + 0x10</code> です。ここから、その関数がどこで対象を受け取ったかを呼び出し元へたどります。再現できる場合は、生きているプロセスにブレークポイントを置き、問題の値が作られたところを追えます。<a href="https://learn.microsoft.com/en-us/shows/inside/c0000005" target="_blank" rel="noreferrer">Microsoftのアクセス違反の読み方</a> · <a href="/study/tools/windows/debugger-breakpoints-and-watchpoints.html">ブレークポイントとデータブレークポイント</a> · <a href="/study/tools/build/debugging-and-analysis.html">静的解析とサニタイザー</a></p>`,15)])])}const u=a(t,[["render",d]]);export{h as __pageData,u as default};
